// --- conversion helpers ---

func toSourceState(run *database2.WorkspaceSyncRun, threshold time.Duration) domain.SourceState {
	if run == nil {
		return domain.DeriveSourceState(nil, threshold)
	}
	sr := &domain.SyncRun{
		ID:          database2.UUIDString(run.ID),
		WorkspaceID: database2.UUIDString(run.WorkspaceID),
		Trigger:     run.Trigger,
		Mode:        run.Mode,
		Status:      domain.SyncStatus(run.Status),
		StartedAt:   run.StartedAt.Time,
	}
	if run.FinishedAt.Valid {
		t := run.FinishedAt.Time
		sr.FinishedAt = &t
	}
	if run.CommitSha != nil {
		sr.CommitSHA = *run.CommitSha
	}
	if run.ErrorCode != nil {
		sr.ErrorCode = *run.ErrorCode
	}
	if run.ErrorMessage != nil {
		sr.ErrorMsg = *run.ErrorMessage
	}
	return domain.DeriveSourceState(sr, threshold)
}

func toTaskSummary(t database2.WorkspaceTask) domain.TaskSummary {
	isBlocked := t.Status != nil && *t.Status == "blocked"
	return domain.TaskSummary{
		ID:            database2.UUIDString(t.ID),
		TaskID:        database2.UUIDString(t.TaskID),
		TaskName:      t.TaskName,
		FeatureID:     database2.UUIDString(t.FeatureID),
		FeatureName:   t.FeatureName,
		Title:         t.Title,
		Status:        derefStr(t.Status),
		Repo:          derefStr(t.Repo),
		Branch:        derefStr(t.Branch),
		IsBlocked:     isBlocked,
		BlockedReason: derefStr(t.BlockedReason),
		Pr:            rawJSONOrNil(t.Pr),
		WorkspacePr:   rawJSONOrNil(t.WorkspacePr),
	}
}

func toActivityEvent(a database2.WorkspaceActivityEvent) domain.ActivityEvent {
	e := domain.ActivityEvent{
		Action:    derefStr(a.Action),
		Scope:     a.ScopeType,
		Actor:     derefStr(a.Actor),
		Note:      derefStr(a.Note),
		FeatureID: database2.UUIDString(a.FeatureID),
		TaskID:    database2.UUIDString(a.TaskID),
	}
	if a.OccurredAt != nil {
		if t, err := time.Parse(time.RFC3339, *a.OccurredAt); err == nil {
			e.OccurredAt = t
		}
	}
	return e
}

func isValidSearchSort(sort string) bool {
	switch sort {
	case "title_asc", "title_desc", "status_asc", "status_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
		return true
	default:
		return false
	}
}

func isValidTaskSearchSort(sort string) bool {
	switch sort {
	case "task_id_asc", "task_id_desc", "title_asc", "title_desc", "status_asc", "status_desc", "repo_asc", "repo_desc", "updated_at_asc", "updated_at_desc", "time_asc", "time_desc", "createdAt", "-createdAt":
		return true
	default:
		return false
	}
}

func featureIDs(features []database2.WorkspaceFeature) []string {
	ids := make([]string, 0, len(features))
	for _, feature := range features {
		ids = append(ids, database2.UUIDString(feature.FeatureID))
	}
	return ids
}

func taskCountsFromRows(rows []database2.WorkspaceFeatureTaskCounts) map[string]domain.TaskCounts {
	counts := make(map[string]domain.TaskCounts, len(rows))
	for _, row := range rows {
		counts[database2.UUIDString(row.FeatureID)] = domain.TaskCounts{
			Total:      int(row.Total),
			Done:       int(row.Done),
			InProgress: int(row.InProgress),
			Blocked:    int(row.Blocked),
			Ready:      int(row.Ready),
			Todo:       int(row.Todo),
		}
	}
	return counts
}

func countTasksByFeature(tasks []database2.WorkspaceTask) map[string]domain.TaskCounts {
	counts := make(map[string]domain.TaskCounts, len(tasks))
	for _, t := range tasks {
		featureID := database2.UUIDString(t.FeatureID)
		current := counts[featureID]
		current.Total++
		if t.Status != nil {
			switch *t.Status {
			case "done":
				current.Done++
			case "in_progress":
				current.InProgress++
			case "blocked":
				current.Blocked++
			case "ready":
				current.Ready++
			case "todo":
				current.Todo++
			}
		}
		counts[featureID] = current
	}
	return counts
}

func countTasks(tasks []database2.WorkspaceTask) domain.TaskCounts {
	var counts domain.TaskCounts
	for _, t := range tasks {
		counts.Total++
		if t.Status != nil {
			switch *t.Status {
			case "done":
				counts.Done++
			case "in_progress":
				counts.InProgress++
			case "blocked":
				counts.Blocked++
			case "ready":
				counts.Ready++
			case "todo":
				counts.Todo++
			}
		}
	}
	return counts
}

